raw_shacl_shapes:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix wf: <http://mnemosyne.dev/workflow#> .
@prefix agt: <http://mnemosyne.dev/agent#> .

wf:RunBoundToSessionShape a sh:NodeShape ;
    sh:targetClass wf:Run ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WF-3: wf:Run wf:boundToAgent target must be typed agt:Session." ;
        sh:select """
            PREFIX wf: <http://mnemosyne.dev/workflow#>
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this wf:boundToAgent ?session .
              FILTER NOT EXISTS { ?session a agt:Session . }
            }
        """ ;
    ] .

wf:AgentRunBoundToTurnShape a sh:NodeShape ;
    sh:targetClass wf:AgentRun ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WF-3: wf:AgentRun wf:boundToAgent target must be typed agt:Turn." ;
        sh:select """
            PREFIX wf: <http://mnemosyne.dev/workflow#>
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this wf:boundToAgent ?turn .
              FILTER NOT EXISTS { ?turn a agt:Turn . }
            }
        """ ;
    ] .
